  'useEverywhere.section.overview.tab': '╨₧╨│╨╗╤Å╨┤',
  'useEverywhere.section.overview.heading': 'Open Design ╨┐╤Ç╨░╤å╤Ä╤ö ╨▓╤ü╤Ä╨┤╨╕, ╨┤╨╡ ╨┐╤Ç╨░╤å╤Ä╤ö ╨▓╨░╤ê agent',
  'useEverywhere.section.overview.intro': 'Open Design ΓÇö ╤å╨╡ ╨▒╤û╨╗╤î╤ê╨╡, ╨╜╤û╨╢ ╨┐╤Ç╨╛╤ü╤é╨╛ ╨▓╤û╨║╨╜╨╛: ╤å╨╡ ╨╗╨╛╨║╨░╨╗╤î╨╜╨╕╨╣ ╨┐╤Ç╨╕╨▓╤û╨╗╨╡╨╣╨╛╨▓╨░╨╜╨╕╨╣ ╨┤╨╡╨╝╨╛╨╜ (`od`) ╨┐╨╗╤Ä╤ü ╤Ç╨╡╤ö╤ü╤é╤Ç Skills + Design-Systems + Atoms. ╨⌐╨╛╨╣╨╜╨╛ ╨▓╤û╨╜ ╨╖╨░╨┐╤â╤ë╨╡╨╜╨╕╨╣ ╨╜╨░ ╨▓╨░╤ê╤û╨╣ ╨╝╨░╤ê╨╕╨╜╤û, ╨▒╤â╨┤╤î-╤Å╨║╨╕╨╣ ╨║╨╛╨┤╨╛╨▓╨╕╨╣ Agent (Claude Code, Codex, Cursor, OpenCode/openclaw, Hermes, ╨▓╨░╤ê ╨▓╨╗╨░╤ü╨╜╨╕╨╣ ╤ü╨║╤Ç╨╕╨┐╤é) ╨╝╨╛╨╢╨╡ ╨║╨╡╤Ç╤â╨▓╨░╤é╨╕ ╨│╨╡╨╜╨╡╤Ç╨░╤å╤û╤Å╨╝╨╕, ╨┐╨╡╤Ç╨╡╨▓╤û╤Ç╤Å╤é╨╕ ╨┐╤Ç╨╛╤ö╨║╤é╨╕ ╤é╨░ ╤ü╤é╨▓╨╛╤Ç╤Ä╨▓╨░╤é╨╕ ╨┤╨╕╨╖╨░╨╣╨╜-╨░╤Ç╤é╨╡╤ä╨░╨║╤é╨╕ ╤ç╨╡╤Ç╨╡╨╖ ╤ç╨╛╤é╨╕╤Ç╨╕ ╨▓╨╖╨░╤ö╨╝╨╛╨╖╨░╨╝╤û╨╜╨╜╤û ╤û╨╜╤é╨╡╤Ç╤ä╨╡╨╣╤ü╨╕.',
  'useEverywhere.section.overview.bullet1': 'CLI ΓÇö `od <command>` ╨┤╨╗╤Å ╨▒╨╡╨╖╨│╨╛╨╗╨╛╨▓╨╕╤à ╤ü╨║╤Ç╨╕╨┐╤é╤û╨▓, CI ╤é╨░ ╨░╨▓╤é╨╛╨╝╨░╤é╨╕╨╖╨░╤å╤û╤ù ╨▓ ╨╛╨▒╨╛╨╗╨╛╨╜╤å╤û.',
  'useEverywhere.section.overview.bullet2': 'MCP ╤ü╨╡╤Ç╨▓╨╡╤Ç ΓÇö ╨┐╤û╨┤╨║╨╗╤Ä╤ç╨░╤ö Open Design ╤Å╨║ ╤ü╨╡╤Ç╨▓╨╡╤Ç Model Context Protocol, ╤ë╨╛╨▒ ╨▒╤â╨┤╤î-╤Å╨║╨╕╨╣ Agent ╨╖ ╨┐╤û╨┤╤é╤Ç╨╕╨╝╨║╨╛╤Ä MCP ╨╝╤û╨│ ╨┐╨╡╤Ç╨╡╨│╨╗╤Å╨┤╨░╤é╨╕ ╨╜╨░╨▓╨╕╤ç╨║╨╕, ╨╖╨░╨┐╤â╤ü╨║╨░╤é╨╕ ╤ü╤å╨╡╨╜╨░╤Ç╤û╤ù ╤é╨░ ╤ç╨╕╤é╨░╤é╨╕ ╨░╤Ç╤é╨╡╤ä╨░╨║╤é╨╕.',
