  'useEverywhere.section.cli.snippet4': '╨ƒ╨╡╤Ç╨╡╨▓╤û╤Ç╨╕╤é╨╕ ╨╖╨░╨▓╨░╨╜╤é╨░╨╢╨╡╨╜╤û ╨░╤Ç╤é╨╡╤ä╨░╨║╤é╨╕ ╤ç╨╡╤Ç╨╡╨╖ CLI',
