  'useEverywhere.section.cli.footer': '╨ú╤ü╤û ╨┐╤û╨┤╨║╨╛╨╝╨░╨╜╨┤╨╕ ╨┐╤Ç╨╕╨╣╨╝╨░╤Ä╤é╤î `--daemon-url http://127.0.0.1:<port>`, ╤ë╨╛╨▒ ╨╖╨▓╨╡╤Ç╨╜╤â╤é╨╕╤ü╤Å ╨┤╨╛ ╨║╨╛╨╜╨║╤Ç╨╡╤é╨╜╨╛╨│╨╛ ╨╖╨░╨┐╤â╤ë╨╡╨╜╨╛╨│╨╛ ╨┤╨╡╨╝╨╛╨╜╨░ ΓÇö ╨║╨╛╤Ç╨╕╤ü╨╜╨╛ ╨┐╤û╨┤ ╤ç╨░╤ü ╨╖╨░╨┐╤â╤ü╨║╤â ╤û╨╖╨╛╨╗╤î╨╛╨▓╨░╨╜╨╛╨│╨╛ ╨┤╤Ç╤â╨│╨╛╨│╨╛ ╨╡╨║╨╖╨╡╨╝╨┐╨╗╤Å╤Ç╨░ ╨┤╨╗╤Å ╤é╨╡╤ü╤é╤û╨▓.',
  'useEverywhere.section.mcp.tab': '╨í╨╡╤Ç╨▓╨╡╤Ç MCP',
  'useEverywhere.section.mcp.heading': '╨¥╨░╨┤╨░╨╣╤é╨╡ Open Design ╤Å╨║ ╤ü╨╡╤Ç╨▓╨╡╤Ç MCP ╨▒╤â╨┤╤î-╤Å╨║╨╛╨╝╤â agent ╨┤╨╗╤Å ╨║╨╛╨┤╤â╨▓╨░╨╜╨╜╤Å',
  'useEverywhere.section.mcp.intro': 'Open Design ╨┐╨╛╤ü╤é╨░╤ç╨░╤ö╤é╤î╤ü╤Å ╤û╨╖ ╤ü╨╡╤Ç╨▓╨╡╤Ç╨╛╨╝ Model Context Protocol (`od mcp`), ╤Å╨║╨╕╨╣ ╨┤╨╛╨╖╨▓╨╛╨╗╤Å╤ö ╨▒╤â╨┤╤î-╤Å╨║╨╛╨╝╤â ╨║╨╗╤û╤ö╨╜╤é╤â ╨╖ ╨┐╤û╨┤╤é╤Ç╨╕╨╝╨║╨╛╤Ä MCP ΓÇö Cursor, Claude Code, Antigravity, VS Code Copilot Chat, openclaw, hermes ΓÇö ╨▓╨╕╤Å╨▓╨╗╤Å╤é╨╕ ╤û╨╜╤ü╤é╤Ç╤â╨╝╨╡╨╜╤é╨╕ Open Design (╨┐╨╡╤Ç╨╡╨│╨╗╤Å╨┤ ╨╜╨░╨▓╨╕╤ç╨╛╨║, ╤Ç╨╡╨╜╨┤╨╡╤Ç╨╕╨╜╨│ ╨┐╨╛╨┐╨╡╤Ç╨╡╨┤╨╜╤û╤à ╨┐╨╡╤Ç╨╡╨│╨╗╤Å╨┤╤û╨▓, ╨│╨╡╨╜╨╡╤Ç╨░╤å╤û╤Å ╨╝╨╡╨┤╤û╨░, ╨╖╨░╨┐╤â╤ü╨║ ╨┐╨╗╨░╨│╤û╨╜╤û╨▓) ╨▒╨╡╨╖ ╤Ç╤â╤ç╨╜╨╛╨│╨╛ ╨▓╨╕╨║╨╗╨╕╨║╤â ╤ç╨╡╤Ç╨╡╨╖ ╨╛╨▒╨╛╨╗╨╛╨╜╨║╤â. ╨ö╨╡╨╝╨╛╨╜ ╨┐╤â╨▒╨╗╤û╨║╤â╤ö ╨│╨╛╤é╨╛╨▓╨╕╨╣ ╨┤╨╛ ╨▓╤ü╤é╨░╨▓╨╗╨╡╨╜╨╜╤Å ╤ä╤Ç╨░╨│╨╝╨╡╨╜╤é ╨┤╨╗╤Å ╨▓╤ü╤é╨░╨╜╨╛╨▓╨╗╨╡╨╜╨╜╤Å ╤ç╨╡╤Ç╨╡╨╖ `GET /api/mcp/install-info` ╨┤╨╗╤Å ╨║╨╛╨╢╨╜╨╛╨│╨╛ ╨╛╤ü╨╜╨╛╨▓╨╜╨╛╨│╨╛ ╨║╨╗╤û╤ö╨╜╤é╨░.',
