  'useEverywhere.section.mcp.bullet2': '╨É╨▓╤é╨╛╨╝╨░╤é╨╕╤ç╨╜╨╛ ╨▓╨╕╤Å╨▓╨╗╤Å╤ö URL ╨░╨║╤é╨╕╨▓╨╜╨╛╨│╨╛ daemon ╤ç╨╡╤Ç╨╡╨╖ ╨╗╨╛╨║╨░╨╗╤î╨╜╨╕╨╣ ╤ü╨╛╨║╨╡╤é ╤ü╤é╨░╤é╤â╤ü╤â IPC, ╨║╨╛╨╗╨╕ ╨╖╨░╨┐╤â╤ë╨╡╨╜╨╛ ╤Å╨║ sidecar.',
