  'settings.memoryStarterFeedbackBody': '- ╨ó╨╡╨╝╨░: ╤é╨╡╨╝╨╜╨░ ╨╖╨░ ╨╖╨░╨╝╨╛╨▓╤ç╤â╨▓╨░╨╜╨╜╤Å╨╝\n- ╨₧╤ü╨╜╨╛╨▓╨╜╨╕╨╣ ╤é╨╡╨║╤ü╤é: ΓëÑ 18px\n- ╨⌐╤û╨╗╤î╨╜╤û╤ü╤é╤î ╤û╨╜╤ä╨╛╤Ç╨╝╨░╤å╤û╤ù: ╨╜╨░╨┤╨░╨▓╨░╨╣╤é╨╡ ╨┐╨╡╤Ç╨╡╨▓╨░╨│╤â ╨┐╤Ç╨╛╤ü╤é╨╛╤Ç╤â, ╨╝╨╡╨╜╤ê╨╡ ╨╡╨╗╨╡╨╝╨╡╨╜╤é╤û╨▓ ╨╜╨░ ╨╡╨║╤Ç╨░╨╜\n\n╨º╨╛╨╝╤â: ╨╝╨╡╨╜╤ê╨╡ ╨╜╨░╨▓╨░╨╜╤é╨░╨╢╨╡╨╜╨╜╤Å ╨╜╨░ ╨╛╤ç╤û ╨┐╤û╨┤ ╤ç╨░╤ü ╤é╤Ç╨╕╨▓╨░╨╗╨╕╤à ╤ü╨╡╤ü╤û╨╣.\n╨Ü╨╛╨╗╨╕ ╨╖╨░╤ü╤é╨╛╤ü╨╛╨▓╤â╨▓╨░╤é╨╕: ╤ë╨╛╤Ç╨░╨╖╤â, ╨║╨╛╨╗╨╕ ╨▓╨╕ ╨│╨╡╨╜╨╡╤Ç╤â╤ö╤é╨╡ UI, ╨▓╨╡╨▒╤ü╤é╨╛╤Ç╤û╨╜╨║╨╕ ╨░╨▒╨╛ ╤ü╨╗╨░╨╣╨┤╨╕.',
